/* Druga wersja kierunku Clear. Pozostałe kierunki zostają do porównania. */
Object.assign(themes.clear,{
 name:'Clear / 04',tag:'CLEAR / WERSJA 04',title:'Jasna przestrzeń. Mocny kontrast.',
 desc:'Kolorystyka Clear 03. Miękkie białe powierzchnie, subtelna głębia i grafitowe obszary najważniejszych działań — rozwinięte według Twoich referencji.',
 colors:['#242724','#C23D22','#F3F4F1','#FFFFFF'],labels:['Grafit / tekst i akcje','Cynober / marka','Szarość / powierzchnie','Biel / tło'],heading:'DM Sans',body:'DM Sans',
 brand:'Praca w Belgii. Jasne warunki.',rationale:'Rozpoznawalne „be”, grafit i cynober pozostają fundamentem marki. Białe powierzchnie unoszą się nad neutralnym tłem. Grafit wyodrębnia wyszukiwanie i podsumowania, a czerwony akcent wskazuje działanie. Większa typografia i miękkie krawędzie łączą przejrzystość z wyrazistym charakterem.',
 geometry:'Powierzchnie o promieniu 20–28 px. Przyciski i nawigacja w zaokrąglonych kształtach. Rytm 8 px. Jedna spójna powierzchnia dla powiązanych danych. Cyfry tabelaryczne dla wynagrodzeń.',
 voice:'Krótko, po ludzku, bez motywacyjnych sloganów. „Oferty pracy w Belgii”, „12 nowych aplikacji”, „Dodaj uprawnienia”. Konkret przed obietnicą.'
});
const previousHome=home;
home=function(){if(theme!=='clear')return previousHome();return `${nav()}<main><section class="clear-intro"><div class="intro-heading"><span class="location-note">Praca w Belgii</span><h1>Praca w Belgii.<br><span>Na jasnych warunkach.</span></h1></div><div class="intro-copy"><p>Stawka, miejsce, wymagania.<br>Sprawdź konkrety i wybierz ofertę.</p><p class="quiet">Do aplikowania wystarczy prosty profil zawodowy.</p></div></section><section class="clear-search">${search()}<div class="popular"><span>Przeglądaj branże</span>${['Logistyka','Produkcja','Budownictwo','Technika'].map((x,i)=>`<button data-category="${x}"><span class="category-index">0${i+1}</span>${x}</button>`).join('')}</div></section><section class="clear-jobs"><div class="clear-jobs-intro"><span class="location-note">Aktualne oferty</span><h2>Sprawdź,<br>kto szuka.</h2><p>Porównaj warunki.<br>Zapisz to, co Ci odpowiada.</p>${button('Wszystkie oferty','jobs','text-link')}<div class="local-note"><span class="be-stamp">be</span><span>Antwerpia. Gandawa.<br>Bruksela. I dalej.</span></div></div><div class="clear-job-list"><div class="job-table-head"><span>Stanowisko i firma</span><span>Wynagrodzenie</span></div>${jobs.map(j=>jobCard(j,false)).join('')}</div></section><section class="clear-bottom"><div><span class="location-note">DLA KANDYDATÓW</span><h2>Nie masz CV?<br>Opowiedz o swoim doświadczeniu.</h2><p>W profilu podajesz zawód, umiejętności i znajomość języków. Pracodawca może wysłać Ci propozycję pracy.</p>${button('Zobacz profil kandydata','candidate','text-link')}</div><div><span class="location-note">DLA PRACODAWCÓW</span><h2>Zacznij od ludzi,<br>których potrzebujesz.</h2><p>Oferty, zgłoszenia i rozmowy w jednym miejscu. Bez gubienia się między wiadomościami.</p>${button('Przejdź do panelu','employer','text-link')}</div></section></main>${footer()}`;};
const previousBrand=brand;
brand=function(){if(theme!=='clear')return previousBrand();const t=themes.clear;return `${nav()}<main class="brand-board"><div class="brand-hero"><div><span class="location-note">CLEAR / IDENTYFIKACJA 04</span><h1>Pracuj.<br>W Belgii.</h1><p>${t.rationale}</p></div><div class="brand-logo">${logo()}</div></div><div class="palette-list">${t.colors.map((c,i)=>`<div class="color-item"><div class="color-box" style="background:${c}"></div><strong>${t.labels[i]}</strong><span>${c}</span></div>`).join('')}</div><div class="brand-grid"><article><span class="location-note">TYPOGRAFIA</span><div class="specimen">Aa 012<br>ąęłńó</div><h3>DM Sans</h3><p>Jedna rodzina, trzy grubości. Duże nagłówki bez pogrubiania każdego słowa. Dane liczbowe w stałej szerokości. Tekst główny 16–18 px.</p></article><article><span class="location-note">KOMPOZYCJA</span><h2>Informacja<br>ma pierwszeństwo.</h2><p>${t.geometry}</p><div class="brand-sample"><span class="btn">Szukaj pracy</span><span class="btn secondary">Moje konto</span></div></article><article><span class="location-note">JĘZYK</span><h2>„17–20 € brutto.<br>Antwerpia.”</h2><p>${t.voice}</p><p>Kolor marki nie oznacza błędu. Komunikaty o powodzeniu i błędach dostają osobną ikonę, opis i kolor statusu.</p></article></div><section class="logo-spec"><div><span class="location-note">SYGNET I WERSJE JEDNOBARWNE</span><h2>„be” jest punktem rozpoznawczym.</h2><p>Bez dodatkowej litery „p” przed nazwą. Sygnet i końcówka logotypu mają ten sam kształt. Pole ochronne: połowa wysokości znaku.</p></div><div class="stamp-set"><span class="be-stamp">be</span><span class="be-stamp mono">be</span><span class="be-stamp inverse">be</span></div></section><p>Fotografia: prawdziwe warsztaty, magazyny i zespoły przy pracy. Naturalne światło, codzienne kadry, bez inscenizowanych uścisków dłoni. W ekranach roboczych pierwszeństwo mają treści i dane.</p></main>${footer()}`;};
const previousEmployer=employer;
employer=function(){let html=previousEmployer();if(theme!=='clear')return html;return html.replace('Dobry zespół zaczyna się tutaj.','Rekrutacja').replace('Najważniejsze informacje o Twojej rekrutacji.','12 nowych aplikacji czeka na przejrzenie.').replace('Rekrutacja w liczbach','Przebieg rekrutacji');};
const previousCandidate=candidate;
candidate=function(){let html=previousCandidate();if(theme!=='clear')return html;return html.replace('TWÓJ NASTĘPNY KROK','TWOJE KONTO').replace('Twoje aplikacje, propozycje i możliwości — w jednym miejscu.','Masz nową propozycję pracy i jedno zaproszenie na rozmowę.').replace('Jeszcze jeden krok, by lepiej pokazać swoje doświadczenie.','Dodaj uprawnienia. Pozostałe informacje są już uzupełnione.');};
const previousJobList=jobList;
jobList=function(){let html=previousJobList();return theme==='clear'?html.replace('Znajdź swoje miejsce.','Oferty pracy w Belgii.'):html;};
render();
